#' Plot *s2dv* climate data
#' 
#' @description Plots *s2dv_cube* postprocessing skill scores for gridded, polygon 
#' and point data generated by the `c4h_postprocessing` function. It is used for
#' the following statistics: BSS, RPSS, CRPSS, AbsBiasSS, MSSS, RMSSS and ROCSS.
#' For MSE and RMSE,please use the function `c4h_plot`.
#'
#' @param skill *s2dv_cube* object with the skill data to be plotted.
#' @param sign An additional optional binary *s2dv_cube* indicating significance.
#' @param sdate Numerical index of the forecast starting time to be plotted. Defaults 
#' to NULL (all starting dates).
#' @param time Numerical index of the time to be plotted. Defaults to NULL (all 
#' times).
#' @param ensemble Numerical index of the ensemble member to be plotted. If
#' set to TRUE, it aggregates all the ensemble members. Defaults to NULL (all 
#' times).
#' @param boundaries Polygon boundaries to add to the map.  Set to NULL for no 
#' boundaries (default), otherwise supply a polygon `sf` object or set to 
#' "countries" for coarse country boundaries.
#' @param mask_boundaries If TRUE (default), mask the data to the provided 
#' boundaries.
#' @param ensemble_fun Aggregation function used when ensemble = TRUE.
#' Defaults to the mean.
#' @param title Optional plot title.
#' @param legend Optional legend title. If NULL (default), it uses the variable
#' names.
#' @param palette GHR, RColorBrewer or colorspace palette. Use "-" before the 
#' palette name (e.g., "-Reds") to reverse it. Alternatively, a vector of
#' hex codes to create a continuous interpolated palette.
#' @param noskillcol Colour for skill scores < 0 depicting a skill lower than 
#' climatologies.
#' @param coordgrid If TRUE, display coordinate grids on the map.
#' @param ... Extra arguments indicating fixed aesthetics to be passed to 
#'`stars::geom_stars`, including `lwd`, `alpha` and `colour`.
#' @returns A plot
#' @export
#' 
#' @seealso [c4h_postprocess()],  [c4h_plot()]
#' @examples 
#' hcst <- c4h_load(system.file("extdata", "hindcast", package = "clim4health"),
#'                  variable = "t2m",
#'                  year = 2010:2012,
#'                  month = 1,
#'                  leadtime_month = 1:3,
#'                  ext = "nc")
#' lats <- hcst$coords$latitude
#' lons <- hcst$coords$longitude
#' obs <- c4h_load(system.file("extdata", "reanalysis", package = "clim4health"),
#'                 variable = "t2m",
#'                 year = 2010:2012,
#'                 month = 1,
#'                 leadtime_month = 1:3,
#'                 bbox = c(max(lats), min(lons),
#'                          min(lats), max(lons)),
#'                 ext = "nc")
#' shp_path <- system.file("extdata", "areas", "munip_vallecauca.gpkg",
#'                         package = "clim4health")
#'                         
#' # Postprocess area                         
#' obs <- c4h_space(obs,
#'                  areas = shp_path,
#'                  fun = "mean",
#'                  areas_id = "munip_code")
#' hcst <- c4h_space(hcst,
#'                   areas = shp_path,
#'                   fun = "mean",
#'                   areas_id = "munip_code")
#' skill <- c4h_postprocess(exp = hcst,
#'                          obs = obs,
#'                          metrics = c("BSS", "CRPSS"),
#'                          brier_thresholds = c(0.1, 0.9))
#' # Make some artificial significance for testing
#' skill$CRPSS$sign$data[1, 1, 1, 1:3, 1, sample(1:42, 10)] <- TRUE
#' c4h_plotskill(skill = skill$CRPSS$crpss,
#'               sign = skill$CRPSS$sign)                         


# skill <- skill$CRPSS$crpss
# sign = NULL
# sdate = NULL
# time = NULL
# ensemble = NULL
# ensemble_fun = mean
# boundaries = NULL
# mask_boundaries = FALSE
# title = NULL
# legend = NULL
# palette = "-RdBu"
# coordgrid = FALSE

c4h_plotskill <- function(skill,
                          sign = NULL,
                          sdate = NULL,
                          time = NULL,
                          ensemble = NULL,
                          ensemble_fun = mean,
                          boundaries = NULL,
                          mask_boundaries = FALSE,
                          title = NULL,
                          legend = NULL,
                          palette = "-Green",
                          noskillcol = "#D0C1F5",
                          coordgrid = FALSE,
                          ...) {
  
  # 1. Data checks ----
  
  # Get skill array info
  if (inherits(skill, "s2dv_cube")) {
    dims_skill <- skill$dims
    plot_skill <- skill$data
  } else {
    stop("'skill' must be an s2dv array.")
  }
  
  # Requirements: skill data
  if (any(plot_skill > 1)) {
    stop("'skill' data must be lower than 1. Please use 'c4h_plot'",
         " for other metrics.")
  }
  
  # Get significance array info and requirements
  if (!is.null(sign)) {
    if (inherits(sign, "s2dv_cube")) {
      dims_sign <- sign$dims
      plot_sign <- sign$data
    } else {
      stop("'sign' must be an s2dv array.")
    }
    if (!is.logical(plot_sign)) {
      stop("'sign' data must be of type logical (TRUE/FALSE).")
    }
    if (!identical(dims_skill, dims_sign)) {
      stop("The dimensions of 'skill' and 'sign' must be identical.")
    }
  }
  
  # Requirements: sdate
  if (!is.null(sdate) & !is.numeric(sdate)) {
    stop("'sdate' must be of type numeric.")
  } else if (!is.null(sdate) & any(sdate > dims_skill["sdate"])) {
    stop(paste0("A wrong 'sdate' has been selected (possible range: 1 - ",
                dims_skill["sdate"], ")."))
  } else if (is.null(sdate)) {
    sdate <- 1:dims_skill["sdate"]
  }
  
  # Requirements: time
  if (!is.null(time) & !is.numeric(time)) {
    stop("'time' must be of type numeric.")
  } else if (!is.null(time) & any(time > dims_skill["time"])) {
    stop(paste0("A wrong 'time' has been selected (possible range: 1 - ",
                dims_skill["time"], ")."))
  } else if (is.null(time)) {
    time <- 1:dims_skill["time"]
  }
  
  # Requirements: ensemble
  if (!is.null(ensemble) & !isTRUE(ensemble) & !is.numeric(ensemble)) {
    stop("'ensemble' must be either TRUE, NULL, or of type numeric.")
  } else if (!is.null(ensemble) & !isTRUE(ensemble) & any(ensemble > dims_skill["ensemble"])) {
    stop(paste0("A wrong 'ensemble' has been selected (possible range: 1 - ",
                dims_skill["time"], ")."))
  } else if (is.null(ensemble)) {
    ensemble <- 1:dims_skill["ensemble"]
  }
  
  # Only two dimensions can have length > 1
  if (length(sdate) > 1 & length(time) > 1 & length(ensemble) > 1) {
    stop(paste0("Only two out of 'sdate', 'time' and 'ensemble' can have a ",
                "length larger than one."))
  } else{
    
    # Faceting requirements
    facet_vars <- list(sdate = sdate, time = time, ensemble = ensemble)
    facet_vars <- names(facet_vars)[sapply(facet_vars, function(x) length(x) > 1)]
    f1 <- if (length(facet_vars) >= 1) facet_vars[1] else NULL
    f2 <- if (length(facet_vars) >= 2) facet_vars[2] else NULL
  }
  
  # Requirements: boundaries 
  if (!is.null(boundaries)) {
    if (!inherits(boundaries, "sf")) {
      if (boundaries != "countries") {
        stop("'boundaries' must be set to either 'countries' or be a ",
             "polygon 'sf' object.")
      }
    }
  }
  
  # Number of panels
  if (length(time) * length(sdate) * length(ensemble) > 30) {
    warning(paste0("The number of panels is very large, consider selecting a ",
                   "smaller set of times/ensemble members/start dates."))
  }
  
  # 2. Data preparation ----
  
  # Identify reanalysis/stations/areas and transform 'time' dimension if needed
  if (dims_skill["sdate"] == 1) {
    skill$coords$time <- skill$attrs$Dates
    if (!is.null(sign)) sign$coords$time <- sign$attrs$Dates
  } else {
    skill$coords$sdate <- skill$attrs$Dates[, 1]
    if (!is.null(sign)) sign$coords$sdate <- sign$attrs$Dates[, 1]
  }
  
  # Select 'sdate' if needed
  if (all(sdate %in% 1:dims_skill["sdate"])) {
    plot_skill <- .subset_array_named(plot_skill, sdate = sdate)
    if (!is.null(sign)) plot_sign <- .subset_array_named(plot_sign, sdate = sdate)
  }
  
  # Select 'time' if needed
  if (all(time %in% 1:dims_skill["time"])) {
    plot_skill <- .subset_array_named(plot_skill, time = time)
    if (!is.null(sign)) plot_sign <- .subset_array_named(plot_sign, time = time)
  }
  
  # Aggregate ensemble members if needed
  if ((dims_skill["ensemble"] > 1) & isTRUE(ensemble)) {
    message(paste0("Aggregating ensemble members with the function: ", 
                   deparse(substitute(ensemble_fun))))
    keep_margins <- which(names(dims_skill) != "ensemble")
    plot_skill <- apply(plot_skill, MARGIN = keep_margins, FUN = ensemble_fun)
    dim(plot_skill) <- c(dim(plot_skill), "ensemble" = 1)
    plot_skill <- aperm(plot_skill, perm = match(names(dim(plot_skill)), names(dims_skill)))
    ensemble <- 1
    
    if (!is.null(sign)) {
      plot_sign <- apply(plot_sign, MARGIN = keep_margins, FUN = ensemble_fun)
      dim(plot_sign) <- c(dim(plot_sign), "ensemble" = 1)
      plot_sign <- aperm(plot_sign, perm = match(names(dim(plot_sign)), names(dims_skill)))
    }
    
    # Select ensemble member
  } else if(all(ensemble %in% 1:dims_skill["ensemble"])) {
    plot_skill <- .subset_array_named(plot_skill, ensemble = ensemble)
    if (!is.null(sign)) plot_sign <- .subset_array_named(plot_sign, ensemble = ensemble)
  }
  
  # Select boundaries if needed
  if (!is.null(boundaries)) {
    if (inherits(boundaries, "sf")) {
      if (sf::st_crs(boundaries)$epsg != 4326) {
        message("Transforming 'boundaries' to CRS EPSG 4326")
        bound_sf <- sf::st_transform(boundaries, crs = 4326)
      } else {
        bound_sf <- boundaries
      }
    } else if(boundaries == "countries") {
      bound_sf <- spData::world
    }
  }
  
  # Get varname - Fix in postprocess?
  varname <- skill$attrs$Variable$varName
  
  # 3. Conversion to stars ----
  if ("longitude" %in% names(dims_skill)) { # Gridded data
    
    spatial_dims <- c(which(names(dim(plot_skill)) == "longitude"),
                      which(names(dim(plot_skill)) == "latitude"))
    plot_skill <- aperm(plot_skill, c(spatial_dims, setdiff(1:length(dims_skill), spatial_dims)))
    plot_skill <- stars::st_as_stars(plot_skill)
    names(plot_skill) <- varname
    plot_skill <- stars::st_set_dimensions(plot_skill, "longitude",
                                           values = c(skill$coords$longitude))
    plot_skill <- stars::st_set_dimensions(plot_skill, "latitude",
                                           values = c(skill$coords$latitude))
    plot_skill <- stars::st_set_dimensions(plot_skill, "sdate",
                                           values = c(skill$coords$sdate)[sdate])
    plot_skill <- stars::st_set_dimensions(plot_skill, "ensemble",
                                           values = c(skill$coords$ensemble)[ensemble])
    plot_skill <- stars::st_set_dimensions(plot_skill, "time",
                                           values = c(skill$coords$time)[time]) 
    sf::st_crs(plot_skill) <- 4326
    
    if (!is.null(sign)) {
      plot_sign <- aperm(plot_sign, c(spatial_dims, setdiff(1:length(dims_skill), spatial_dims)))
      plot_skill[["sign"]] <- plot_sign
    }
    
    # Mask if needed
    if (isTRUE(mask_boundaries) & !is.null(boundaries)) {
      sf::sf_use_s2(FALSE) 
      suppressMessages(plot_skill <- plot_skill[bound_sf])
      if (!is.null(sign)) suppressMessages(plot_sign <- plot_sign[bound_sf])
      sf::sf_use_s2(FALSE) 
    }
    
  } else if ("location" %in% names(dims_skill)) { # Point data
    
    lon <- skill$attrs$location$longitude
    lat <- skill$attrs$location$latitude
    point_geom <- sf::st_sfc(lapply(seq_along(lon),
                                    function(i) sf::st_point(c(lon[i], lat[i]))),
                             crs = 4326) 
    plot_skill <- stars::st_as_stars(plot_skill,
                                     dimensions = stars::st_dimensions(
                                       dataset = c(skill$coords$dataset),
                                       var = c(skill$coords$var),
                                       sdate = c(skill$coords$sdate)[sdate],
                                       time = c(skill$coords$time)[time],
                                       ensemble = c(skill$coords$ensemble)[ensemble],
                                       location = point_geom
                                     ))
    names(plot_skill) <- varname
    if (!is.null(sign)) {
      plot_skill[["sign"]] <- plot_sign
    }
    plot_skill <- sf::st_as_sf(plot_skill, long = TRUE)
    
  } else if ("area" %in% names(dims_skill)) { # Polygon data
    
    plot_skill <- stars::st_as_stars(plot_skill,
                                     dimensions = stars::st_dimensions(
                                       dataset = c(skill$coords$dataset),
                                       var = c(skill$coords$var),
                                       sdate = c(skill$coords$sdate)[sdate],
                                       time = c(skill$coords$time)[time],
                                       ensemble = c(skill$coords$ensemble)[ensemble],
                                       area = skill$attrs$area$geom
                                     ))
    names(plot_skill) <- varname
    if (!is.null(sign)) {
      plot_skill[["sign"]] <- plot_sign
    }
    plot_skill <- sf::st_as_sf(plot_skill, long = TRUE)
    
  }
  
  # 4. Plot ----
  
  # Binning, reverse factor
  plot_skill[[varname]] <- cut(plot_skill[[varname]], 
                               breaks = c(-Inf, seq(0, 1, by = 0.1)),
                               labels = paste0("<", seq(0, 1, by = 0.1)))
  plot_skill[[varname]] <- factor(plot_skill[[varname]],
                                  levels = rev(levels(plot_skill[[varname]])))
  
  # Base plot
  if ("longitude" %in% names(dims_skill)) { # Gridded data
    p <- ggplot2::ggplot() +
      stars::geom_stars(data = plot_skill, ...) +
      ggplot2::coord_equal(expand = FALSE)
    
    if (!is.null(sign)) {
      message("Not implemented yet.")
    }
    
  } else if ("location" %in% names(dims_skill)) { # Point data
    if (!is.null(boundaries)) {
      p <- ggplot2::ggplot() +
        ggplot2::geom_sf(data = bound_sf, alpha = 0, 
                         col = "grey10", linewidth = 0.1, inherit.aes = FALSE) +
        ggplot2::geom_sf(data = plot_skill, ggplot2::aes(colour = .data[[varname]]), ...)  +
        ggplot2::scale_x_continuous(labels = function(x) paste0(ifelse(x < 0, "-", ""), abs(x))) +
        ggplot2::scale_y_continuous(labels = function(y) paste0(ifelse(y < 0, "-", ""), abs(y)))
      
      if (!is.null(sign)) {
        message("Not implemented yet.")
      }
      
    } else {
      p <- ggplot2::ggplot() +
        ggplot2::geom_sf(data = plot_skill, ggplot2::aes(colour = .data[[varname]]), ...)  +
        ggplot2::scale_x_continuous(labels = function(x) paste0(ifelse(x < 0, "-", ""), abs(x))) +
        ggplot2::scale_y_continuous(labels = function(y) paste0(ifelse(y < 0, "-", ""), abs(y)))
    }
    
  } else if ("area" %in% names(dims_skill)) { # Polygon data
    if (!is.null(boundaries)) {
      p <- ggplot2::ggplot() +
        ggplot2::geom_sf(data = bound_sf, alpha = 0, 
                         col = "grey10", linewidth = 0.1, inherit.aes = FALSE) +
        ggplot2::geom_sf(data = plot_skill, ggplot2::aes(fill = .data[[varname]]), 
                         ..., inherit.aes = FALSE) +
        ggplot2::coord_sf(
          xlim = sf::st_bbox(plot_skill)[c("xmin", "xmax")],
          ylim = sf::st_bbox(plot_skill)[c("ymin", "ymax")],
          expand = TRUE)   +
        ggplot2::scale_x_continuous(labels = function(x) paste0(ifelse(x < 0, "-", ""), abs(x))) +
        ggplot2::scale_y_continuous(labels = function(y) paste0(ifelse(y < 0, "-", ""), abs(y)))
    } else {
      p <- ggplot2::ggplot() +
        ggplot2::geom_sf(data = plot_skill, ggplot2::aes(fill = .data[[varname]]),
                         ...)   +
        ggplot2::scale_x_continuous(labels = function(x) paste0(ifelse(x < 0, "-", ""), abs(x))) +
        ggplot2::scale_y_continuous(labels = function(y) paste0(ifelse(y < 0, "-", ""), abs(y)))
    }
    if (!is.null(skill)) {
      p <- p + 
        ggpattern::geom_sf_pattern(data = plot_skill[plot_skill$sign,],
                                   ggplot2::aes(pattern = "Significant"),
                                   pattern_alpha = 0.8,
                                   fill = NA) +
        ggpattern::scale_pattern_manual(
          name = "",
          values = c("Significant" = "stripe")) +
        ggplot2::guides(fill = ggplot2::guide_legend(order = 1),
                        pattern = ggplot2::guide_legend(order = 2))
      
    }
  }
  
  # Faceting
  if (!is.null(f1) & is.null(f2)) { # Wrap
    p <- p +
      ggplot2::facet_wrap(stats::as.formula(paste("~", f1)),
                          labeller = "label_both")
  } else if(!is.null(f1) & !is.null(f2)){ # Grid
    
    if (!isTRUE(coordgrid)) {
      p <- p +
        ggplot2::facet_grid(stats::as.formula(paste(f1, "~", f2)),
                            labeller = "label_both", switch = "y")
    } else{
      p <- p +
        ggplot2::facet_grid(stats::as.formula(paste(f1, "~", f2)), labeller = "label_both")      
    }
    
  }
  
  # Palette
  level_names <- unique(plot_skill[[varname]])
  level_names <- level_names[!is.na(level_names)]
  my_palette <- GHRexplore::GHR_palette(palette, length(level_names) - 1)(n = length(level_names) - 1)
  my_palette <- c(my_palette, noskillcol) # Colour for non-significant
  if ("location" %in% names(dims_skill)) {
    p <- p + ggplot2::scale_colour_manual(values = my_palette, na.value = "grey70")  
  } else if ("area" %in% names(dims_skill)) {
    p <- p + ggplot2::scale_fill_manual(values = my_palette, na.value = "grey70")  
  } else {
    p <- p + ggplot2::scale_fill_manual(values = my_palette, na.value = "#00000000")  
  }    
  
  # Boundaries on top, only for grid
  if (!is.null(boundaries) & "longitude" %in% names(dims_skill)) {
    suppressMessages(
      p <- p +
        ggplot2::geom_sf(data = bound_sf, alpha = 0, 
                         col = "grey10", linewidth = 0.1, inherit.aes = FALSE) +
        ggplot2::coord_sf(
          xlim = sf::st_bbox(plot_skill)[c("xmin", "xmax")],
          ylim = sf::st_bbox(plot_skill)[c("ymin", "ymax")],
          expand = TRUE) +
        ggplot2::scale_x_continuous(labels = function(x) paste0(ifelse(x < 0, "-", ""), abs(x))) +
        ggplot2::scale_y_continuous(labels = function(y) paste0(ifelse(y < 0, "-", ""), abs(y)))
    )
  }
  
  # Theme
  if (isTRUE(coordgrid)) {
    
    p <- p +
      ggplot2::theme_minimal() +
      ggplot2::theme(
        plot.margin = ggplot2::theme_bw()$plot.margin,
        panel.background =  ggplot2::element_rect(fill = NA, color = "grey10", linewidth = 0.2),
        panel.grid.minor = ggplot2::element_blank(),
        axis.ticks = ggplot2::element_line(linewidth = 0.3, color = "grey50"),
        axis.text = ggplot2::element_text(size = 7, color = "grey30"),
        strip.text.y = ggplot2::element_text(margin = ggplot2::margin(b = 0)),
        strip.text.x = ggplot2::element_text(margin = ggplot2::margin(b = 0))) +
      ggplot2::xlab("") + ggplot2::ylab("")
    
    if (!isTRUE(coordgrid)) {
      p <- p +
        ggplot2::theme(strip.text.y = ggplot2::element_text(angle = 90))
    }
  } else {
    p <- p + 
      ggplot2::theme_void() +
      ggplot2::theme(
        plot.margin = ggplot2::theme_bw()$plot.margin,
        strip.text.y = ggplot2::element_text(angle = 90, margin = ggplot2::margin(b = 0)),
        strip.text.x = ggplot2::element_text(margin = ggplot2::margin(b = 0)),
        panel.border = ggplot2::element_rect(color = "black", fill = NA, linewidth = 0.1))
  }
  
  # Labels
  if (!is.null(title)) {
    p <- p + ggplot2::ggtitle(title)
  }
  if (!is.null(legend)) {
    if (!"location" %in% names(dims_skill)) {
      p <- p + ggplot2::labs(fill = legend)
    } else {
      p <- p + ggplot2::labs(col = legend)
    }
  }
  
  # Fix labels when time is numeric
  if ((!"sdate" %in% c(f1, f2)) & ("time" %in% c(f1, f2)) & is.numeric(skill$coords$time)) {
    
    if ("longitude" %in% names(dims_skill)) {
      subtitle <- paste0("Start date: ", 
                         stars::st_get_dimension_values(plot_skill, "sdate"))
    } else {
      subtitle <- paste0("Start date: ", plot_skill$sdate[1])
    }
    p <- p +
      ggplot2::labs(subtitle = subtitle)
  }
  
  return(p)
}